def truncate_message(self, message):
    msg_bytes = message.encode('utf-8')

    if len(json.dumps(message)) <= 8015:
        return message

    msg_bytes = msg_bytes[:8000]
    low, high = 0, len(msg_bytes)
    while low < high:
        mid = (low + high + 1) // 2
        if len(json.dumps(_bytes2utf8(msg_bytes[:mid]))) <= 8000:
            low = mid
        else:
            high = mid - 1

    message = _bytes2utf8(msg_bytes[:low])
    return message + "... [truncated]"

